## second question

text = ""

def frequency(text, k):
    dictionary = {}
    max = 0;
    finalString = "";
    for i in range(len(text) - k):
        key = text[i:i+k]
        if key in dictionary:
            dictionary[key] = dictionary[key] + 1
        else:
            dictionary[key] = 1
    
        if dictionary[key] > max:
            max = dictionary[key]

    for key, value in dictionary.items():
        if(value == max):
            finalString = finalString + key + " "

    return (finalString.strip(), max)
        

print(frequency(text, 11))

## Question 3 reverse complement

text = ""
dictionary = {
    "A":"T",
    "C":"G",
    "T":"A",
    "G":"C"
}

def reverseComplement(text):
    complementString = "";
    for i in range(len(text)):
        complementString = complementString + dictionary[text[i]]
    return complementString[::-1]

print(reverseComplement(text))

